7	/**
8	 * Client-side auth configuration for A2A remote agents.
9	 * Corresponds to server-side SecurityScheme types from @a2a-js/sdk.
10	 * @see https://a2a-protocol.org/latest/specification/#451-securityscheme
11	 */
12	
13	import type { AuthenticationHandler } from '@a2a-js/sdk/client';
14	
15	export type A2AAuthProviderType =
16	  | 'google-credentials'
17	  | 'apiKey'
18	  | 'http'
19	  | 'oauth2'
20	  | 'openIdConnect';
21	
22	export interface A2AAuthProvider extends AuthenticationHandler {
23	  readonly type: A2AAuthProviderType;
24	  initialize?(): Promise<void>;
25	}
26	
27	export interface BaseAuthConfig {
28	  agent_card_requires_auth?: boolean;
29	}
30	
31	/** Client config for google-credentials (not in A2A spec, Gemini-specific). */
32	export interface GoogleCredentialsAuthConfig extends BaseAuthConfig {
33	  type: 'google-credentials';
34	  scopes?: string[];
35	}
36	
37	/** Client config corresponding to APIKeySecurityScheme. Only header location is supported. */
38	// TODO: Add 'query' and 'cookie' location support if needed.
39	export interface ApiKeyAuthConfig extends BaseAuthConfig {
40	  type: 'apiKey';
41	  /** The secret. Supports $ENV_VAR, !command, or literal. */
42	  key: string;
43	  /** Header name. @default 'X-API-Key' */
44	  name?: string;
45	}
46	
47	/** Client config corresponding to HTTPAuthSecurityScheme. */
48	export type HttpAuthConfig = BaseAuthConfig & {
49	  type: 'http';
50	} & (
51	    | {
52	        scheme: 'Bearer';
53	        /** For Bearer. Supports $ENV_VAR, !command, or literal. */
54	        token: string;
55	      }
56	    | {
57	        scheme: 'Basic';
58	        /** For Basic. Supports $ENV_VAR, !command, or literal. */
59	        username: string;
60	        /** For Basic. Supports $ENV_VAR, !command, or literal. */
61	        password: string;
62	      }
63	  );
64	
65	/** Client config corresponding to OAuth2SecurityScheme. */
66	export interface OAuth2AuthConfig extends BaseAuthConfig {
67	  type: 'oauth2';
68	  client_id?: string;
69	  client_secret?: string;
70	  scopes?: string[];
71	}
72	
73	/** Client config corresponding to OpenIdConnectSecurityScheme. */
74	export interface OpenIdConnectAuthConfig extends BaseAuthConfig {
75	  type: 'openIdConnect';
76	  issuer_url: string;
77	  client_id: string;
78	  client_secret?: string;
79	  target_audience?: string;
80	  scopes?: string[];
81	}
82	
83	export type A2AAuthConfig =
84	  | GoogleCredentialsAuthConfig
85	  | ApiKeyAuthConfig
86	  | HttpAuthConfig
87	  | OAuth2AuthConfig
88	  | OpenIdConnectAuthConfig;
89	
90	export interface AuthConfigDiff {
91	  requiredSchemes: string[];
92	  configuredType?: A2AAuthProviderType;
93	  missingConfig: string[];
94	}
95	
96	export interface AuthValidationResult {
97	  valid: boolean;
98	  diff?: AuthConfigDiff;
99	}
