7	import type { HttpHeaders } from '@a2a-js/sdk/client';
8	import { BaseA2AAuthProvider } from './base-provider.js';
9	import type { ApiKeyAuthConfig } from './types.js';
10	import { resolveAuthValue, needsResolution } from './value-resolver.js';
11	import { debugLogger } from '../../utils/debugLogger.js';
12	
13	const DEFAULT_HEADER_NAME = 'X-API-Key';
14	
15	/**
16	 * Authentication provider for API Key authentication.
17	 * Sends the API key as an HTTP header.
18	 *
19	 * The API key value can be:
20	 * - A literal string
21	 * - An environment variable reference ($ENV_VAR)
22	 * - A shell command (!command)
23	 */
24	export class ApiKeyAuthProvider extends BaseA2AAuthProvider {
25	  readonly type = 'apiKey' as const;
26	
27	  private resolvedKey: string | undefined;
28	  private readonly headerName: string;
29	
30	  constructor(private readonly config: ApiKeyAuthConfig) {
31	    super();
32	    this.headerName = config.name ?? DEFAULT_HEADER_NAME;
33	  }
34	
35	  override async initialize(): Promise<void> {
36	    if (needsResolution(this.config.key)) {
37	      this.resolvedKey = await resolveAuthValue(this.config.key);
38	      debugLogger.debug(
39	        `[ApiKeyAuthProvider] Resolved API key from: ${this.config.key.startsWith('$') ? 'env var' : 'command'}`,
40	      );
41	    } else {
42	      this.resolvedKey = this.config.key;
43	    }
44	  }
45	
46	  async headers(): Promise<HttpHeaders> {
47	    if (!this.resolvedKey) {
48	      throw new Error(
49	        'ApiKeyAuthProvider not initialized. Call initialize() first.',
50	      );
51	    }
52	    return { [this.headerName]: this.resolvedKey };
53	  }
54	
55	  /**
56	   * Re-resolve command-based API keys on auth failure.
57	   */
58	  override async shouldRetryWithHeaders(
59	    _req: RequestInit,
60	    res: Response,
61	  ): Promise<HttpHeaders | undefined> {
62	    if (res.status !== 401 && res.status !== 403) {
63	      this.authRetryCount = 0;
64	      return undefined;
65	    }
66	
67	    // Only retry for command-based keys that may resolve to a new value.
68	    // Literal and env-var keys would just resend the same failing headers.
69	    if (!this.config.key.startsWith('!') || this.config.key.startsWith('!!')) {
70	      return undefined;
71	    }
72	
73	    if (this.authRetryCount >= BaseA2AAuthProvider.MAX_AUTH_RETRIES) {
74	      return undefined;
75	    }
76	    this.authRetryCount++;
77	
78	    debugLogger.debug(
79	      '[ApiKeyAuthProvider] Re-resolving API key after auth failure',
80	    );
81	    this.resolvedKey = await resolveAuthValue(this.config.key);
82	
83	    return this.headers();
84	  }
85	}
