7	import type { HttpHeaders } from '@a2a-js/sdk/client';
8	import type { A2AAuthProvider, A2AAuthProviderType } from './types.js';
9	
10	/**
11	 * Abstract base class for A2A authentication providers.
12	 * Provides default implementations for optional methods.
13	 */
14	export abstract class BaseA2AAuthProvider implements A2AAuthProvider {
15	  /**
16	   * The type of authentication provider.
17	   */
18	  abstract readonly type: A2AAuthProviderType;
19	
20	  /**
21	   * Get the HTTP headers to include in requests.
22	   * Subclasses must implement this method.
23	   */
24	  abstract headers(): Promise<HttpHeaders>;
25	
26	  protected static readonly MAX_AUTH_RETRIES = 2;
27	  protected authRetryCount = 0;
28	
29	  /**
30	   * Check if a request should be retried with new headers.
31	   *
32	   * The default implementation checks for 401/403 status codes and
33	   * returns fresh headers for retry. Subclasses can override for
34	   * custom retry logic.
35	   *
36	   * @param _req The original request init
37	   * @param res The response from the server
38	   * @returns New headers for retry, or undefined if no retry should be made
39	   */
40	  async shouldRetryWithHeaders(
41	    _req: RequestInit,
42	    res: Response,
43	  ): Promise<HttpHeaders | undefined> {
44	    if (res.status === 401 || res.status === 403) {
45	      if (this.authRetryCount >= BaseA2AAuthProvider.MAX_AUTH_RETRIES) {
46	        return undefined; // Max retries exceeded
47	      }
48	      this.authRetryCount++;
49	      return this.headers();
50	    }
51	    // Reset count if not an auth error
52	    this.authRetryCount = 0;
53	    return undefined;
54	  }
55	
56	  /**
57	   * Initialize the provider. Override in subclasses that need async setup.
58	   */
59	  async initialize(): Promise<void> {
60	    // Default: no-op
61	  }
62	}
