34	/**
35	 * Manages A2A clients and caches loaded agent information.
36	 * Follows a singleton pattern to ensure a single client instance.
37	 */
38	export class A2AClientManager {
39	  private static instance: A2AClientManager;
40	
41	  // Each agent should manage their own context/taskIds/card/etc
42	  private clients = new Map<string, Client>();
43	  private agentCards = new Map<string, AgentCard>();
44	
45	  private constructor() {}
46	
47	  /**
48	   * Gets the singleton instance of the A2AClientManager.
49	   */
50	  static getInstance(): A2AClientManager {
51	    if (!A2AClientManager.instance) {
52	      A2AClientManager.instance = new A2AClientManager();
53	    }
54	    return A2AClientManager.instance;
55	  }
56	
57	  /**
58	   * Resets the singleton instance. Only for testing purposes.
59	   * @internal
60	   */
61	  static resetInstanceForTesting() {
62	    // @ts-expect-error - Resetting singleton for testing
63	    A2AClientManager.instance = undefined;
64	  }
65	
66	  /**
67	   * Loads an agent by fetching its AgentCard and caches the client.
68	   * @param name The name to assign to the agent.
69	   * @param agentCardUrl The full URL to the agent's card.
70	   * @param authHandler Optional authentication handler to use for this agent.
71	   * @returns The loaded AgentCard.
72	   */
73	  async loadAgent(
74	    name: string,
75	    agentCardUrl: string,
76	    authHandler?: AuthenticationHandler,
77	  ): Promise<AgentCard> {
78	    if (this.clients.has(name) && this.agentCards.has(name)) {
79	      throw new Error(`Agent with name '${name}' is already loaded.`);
80	    }
81	
82	    let fetchImpl: typeof fetch = fetch;
83	    if (authHandler) {
84	      fetchImpl = createAuthenticatingFetchWithRetry(fetch, authHandler);
85	    }
86	
87	    const resolver = new DefaultAgentCardResolver({ fetchImpl });
88	
89	    const options = ClientFactoryOptions.createFrom(
90	      ClientFactoryOptions.default,
91	      {
92	        transports: [
93	          new RestTransportFactory({ fetchImpl }),
94	          new JsonRpcTransportFactory({ fetchImpl }),
95	        ],
96	        cardResolver: resolver,
97	      },
98	    );
99	
100	    const factory = new ClientFactory(options);
101	    const client = await factory.createFromUrl(agentCardUrl, '');
102	    const agentCard = await client.getAgentCard();
103	
104	    this.clients.set(name, client);
105	    this.agentCards.set(name, agentCard);
106	
107	    debugLogger.debug(
108	      `[A2AClientManager] Loaded agent '${name}' from ${agentCardUrl}`,
109	    );
110	
111	    return agentCard;
112	  }
113	
114	  /**
115	   * Invalidates all cached clients and agent cards.
116	   */
117	  clearCache(): void {
118	    this.clients.clear();
119	    this.agentCards.clear();
120	    debugLogger.debug('[A2AClientManager] Cache cleared.');
121	  }
122	
123	  /**
124	   * Sends a message to a loaded agent and returns a stream of responses.
125	   * @param agentName The name of the agent to send the message to.
126	   * @param message The message content.
127	   * @param options Optional context and task IDs to maintain conversation state.
128	   * @returns An async iterable of responses from the agent (Message or Task).
129	   * @throws Error if the agent returns an error response.
130	   */
131	  async *sendMessageStream(
132	    agentName: string,
133	    message: string,
134	    options?: { contextId?: string; taskId?: string; signal?: AbortSignal },
135	  ): AsyncIterable<SendMessageResult> {
136	    const client = this.clients.get(agentName);
137	    if (!client) {
138	      throw new Error(`Agent '${agentName}' not found.`);
139	    }
140	
141	    const messageParams: MessageSendParams = {
142	      message: {
143	        kind: 'message',
144	        role: 'user',
145	        messageId: uuidv4(),
146	        parts: [{ kind: 'text', text: message }],
147	        contextId: options?.contextId,
148	        taskId: options?.taskId,
149	      },
150	    };
151	
152	    try {
153	      yield* client.sendMessageStream(messageParams, {
154	        signal: options?.signal,
155	      });
156	    } catch (error: unknown) {
157	      const prefix = `[A2AClientManager] sendMessageStream Error [${agentName}]`;
158	      if (error instanceof Error) {
159	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
160	      }
161	      throw new Error(
162	        `${prefix}: Unexpected error during sendMessageStream: ${String(error)}`,
163	      );
164	    }
165	  }
166	
167	  /**
168	   * Retrieves a loaded agent card.
169	   * @param name The name of the agent.
170	   * @returns The agent card, or undefined if not found.
171	   */
172	  getAgentCard(name: string): AgentCard | undefined {
173	    return this.agentCards.get(name);
174	  }
175	
176	  /**
177	   * Retrieves a loaded client.
178	   * @param name The name of the agent.
179	   * @returns The client, or undefined if not found.
180	   */
181	  getClient(name: string): Client | undefined {
182	    return this.clients.get(name);
183	  }
184	
185	  /**
186	   * Retrieves a task from an agent.
187	   * @param agentName The name of the agent.
188	   * @param taskId The ID of the task to retrieve.
189	   * @returns The task details.
190	   */
191	  async getTask(agentName: string, taskId: string): Promise<Task> {
192	    const client = this.clients.get(agentName);
193	    if (!client) {
194	      throw new Error(`Agent '${agentName}' not found.`);
195	    }
196	    try {
197	      return await client.getTask({ id: taskId });
198	    } catch (error: unknown) {
199	      const prefix = `A2AClient getTask Error [${agentName}]`;
200	      if (error instanceof Error) {
201	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
202	      }
203	      throw new Error(`${prefix}: Unexpected error: ${String(error)}`);
204	    }
205	  }
206	
207	  /**
208	   * Cancels a task on an agent.
209	   * @param agentName The name of the agent.
210	   * @param taskId The ID of the task to cancel.
211	   * @returns The cancellation response.
212	   */
213	  async cancelTask(agentName: string, taskId: string): Promise<Task> {
214	    const client = this.clients.get(agentName);
215	    if (!client) {
216	      throw new Error(`Agent '${agentName}' not found.`);
217	    }
218	    try {
219	      return await client.cancelTask({ id: taskId });
220	    } catch (error: unknown) {
221	      const prefix = `A2AClient cancelTask Error [${agentName}]`;
222	      if (error instanceof Error) {
223	        throw new Error(`${prefix}: ${error.message}`, { cause: error });
224	      }
225	      throw new Error(`${prefix}: Unexpected error: ${String(error)}`);
226	    }
227	  }
228	}
