import type { HttpHeaders } from '@a2a-js/sdk/client';
import { BaseA2AAuthProvider } from './base-provider.js';
import type { HttpAuthConfig } from './types.js';
import { debugLogger } from '../../utils/debugLogger.js';

/**
 * Authentication provider for HTTP authentication schemes.
 *
 * Supports the standard `Bearer` and `Basic` schemes as well as any other
 * user-defined scheme via a raw `value`:
 * - Bearer: `Authorization: Bearer <token>`
 * - Basic: `Authorization: Basic <base64(username:password)>`
 * - Other: `Authorization: <scheme> <value>`
 *
 * Any credential value (token, username, password, or value) may reference an
 * environment variable using the `$ENV_VAR` prefix, in which case it is
 * resolved during {@link initialize}.
 */
export class HttpAuthProvider extends BaseA2AAuthProvider {
  readonly type = 'http' as const;

  private resolvedToken: string | undefined;
  private resolvedUsername: string | undefined;
  private resolvedPassword: string | undefined;
  private resolvedValue: string | undefined;

  constructor(private readonly config: HttpAuthConfig) {
    super();
  }

  /**
   * Resolve a credential, reading it from the environment when it is prefixed
   * with `$`. Otherwise the value is treated as a literal.
   */
  private resolveCredential(value: string): string {
    if (value.startsWith('$')) {
      const envVar = value.slice(1);
      const resolved = process.env[envVar];
      if (resolved === undefined || resolved === '') {
        throw new Error(
          `Environment variable '${envVar}' is not set or is empty. ` +
            `Please set it before using this agent.`,
        );
      }
      debugLogger.debug(`[HttpAuthProvider] Resolved credential from: ${envVar}`);
      return resolved;
    }
    return value;
  }

  override async initialize(): Promise<void> {
    if ('token' in this.config) {
      this.resolvedToken = this.resolveCredential(this.config.token);
    } else if ('username' in this.config) {
      this.resolvedUsername = this.resolveCredential(this.config.username);
      this.resolvedPassword = this.resolveCredential(this.config.password);
    } else {
      this.resolvedValue = this.resolveCredential(this.config.value);
    }
  }

  async headers(): Promise<HttpHeaders> {
    switch (this.config.scheme) {
      case 'Bearer': {
        if (!this.resolvedToken) {
          throw new Error(
            'HttpAuthProvider not initialized. Call initialize() first.',
          );
        }
        return { Authorization: `Bearer ${this.resolvedToken}` };
      }
      case 'Basic': {
        if (!this.resolvedUsername || !this.resolvedPassword) {
          throw new Error(
            'HttpAuthProvider not initialized. Call initialize() first.',
          );
        }
        const encoded = Buffer.from(
          `${this.resolvedUsername}:${this.resolvedPassword}`,
        ).toString('base64');
        return { Authorization: `Basic ${encoded}` };
      }
      default: {
        if (!this.resolvedValue) {
          throw new Error(
            'HttpAuthProvider not initialized. Call initialize() first.',
          );
        }
        return { Authorization: `${this.config.scheme} ${this.resolvedValue}` };
      }
    }
  }

  /**
   * Re-resolve credentials on an authentication failure (401) and retry with
   * the refreshed headers, up to {@link BaseA2AAuthProvider.MAX_AUTH_RETRIES}.
   */
  override async shouldRetryWithHeaders(
    _req: RequestInit,
    res: Response,
  ): Promise<HttpHeaders | undefined> {
    if (res.status !== 401) {
      this.authRetryCount = 0;
      return undefined;
    }

    if (this.authRetryCount >= BaseA2AAuthProvider.MAX_AUTH_RETRIES) {
      return undefined;
    }
    this.authRetryCount++;

    debugLogger.debug(
      '[HttpAuthProvider] Re-initializing credentials after auth failure',
    );
    await this.initialize();

    return this.headers();
  }
}
